-- Source-only fixed262 rollback probe; execution needs separately reviewed target authority.
\set ON_ERROR_STOP on
begin;
set local lock_timeout='1s';
set local statement_timeout='12s';
-- owner-deletion-contracts-begin
-- Eight immutable source frames; pg_temp helpers have no caller SQL/selector inputs.
create function pg_temp.deletion_graph() returns jsonb language plpgsql security definer set search_path='' as $g$
declare result jsonb:='{}'; rel record; rows jsonb;
begin
 for rel in select n.nspname,c.relname from pg_class c join pg_namespace n on n.oid=c.relnamespace
 where c.relkind in('r','p') and n.nspname in('public','private','storage') order by n.nspname,c.relname loop
 execute format('select coalesce(jsonb_agg(to_jsonb(r) order by to_jsonb(r)::text),''[]''::jsonb) from %I.%I r',rel.nspname,rel.relname) into rows;
 result:=result||jsonb_build_object(rel.nspname||'.'||rel.relname,rows);
 end loop;return result;
end;$g$;
-- Only the source-owned material lifecycle clock fields vary between two real writers.
-- Every other row and field remains byte-equivalent in the legacy full-catalog oracle.
create function pg_temp.deletion_comparable(p_graph jsonb) returns jsonb language plpgsql set search_path='' as $g$
declare row jsonb; rows jsonb:='[]'; result jsonb:=p_graph;
begin
 for row in select value from jsonb_array_elements(p_graph->'public.managed_storage_objects') loop
 if row->>'id' in ('a2620000-0000-4000-8000-000000005115','a2620000-0000-4000-8000-000000005116') then row:=row-'updated_at'-'next_attempt_at';end if;
 rows:=rows||jsonb_build_array(row);end loop;
 result:=jsonb_set(result,'{public.managed_storage_objects}',rows);
 rows:='[]';for row in select value from jsonb_array_elements(p_graph->'public.test_document_snapshot_storage_cleanup') loop
 if row->>'id'='a2620000-0000-4000-8000-000000005117'
 then row:=row-'updated_at'-'next_attempt_at';end if;
 rows:=rows||jsonb_build_array(row);end loop;
 return jsonb_set(result,'{public.test_document_snapshot_storage_cleanup}',rows);
end;$g$;
create function pg_temp.expect_deletion_rejection(p_actor uuid,p_test uuid,p_parent uuid,p_expected jsonb,p_code text)
returns void language plpgsql set search_path='' as $g$
declare before_graph jsonb:=pg_temp.deletion_graph(); actual_code text; succeeded boolean:=false;
begin begin
 perform public.test_owner_workflow_v1(p_actor,p_test,p_parent,'delete','{}',p_expected,clock_timestamp()+interval '25 seconds');
 succeeded:=true;
exception when others then get stacked diagnostics actual_code=returned_sqlstate;end;
if succeeded or actual_code is distinct from p_code then raise exception 'Deletion rejection differs';end if;
if pg_temp.deletion_graph() is distinct from before_graph then raise exception 'Rejected deletion changed full catalog';end if;
end;$g$;
create function pg_temp.expect_deletion_closure(p_actor uuid,p_test uuid)
returns void language plpgsql set search_path='' as $g$
declare before_graph jsonb:=pg_temp.deletion_graph(); source jsonb; legacy_graph jsonb; actual_graph jsonb;
legacy_result jsonb; result jsonb; parent uuid; count_before integer; history_ids uuid[]; started timestamptz:=clock_timestamp();
begin
select to_jsonb(t),t.classroom_id into strict source,parent from public.tests t where id=p_test;
select count(*) into count_before from public.test_responses where test_id=p_test;
select coalesce(array_agg(h.id),array[]::uuid[]) into history_ids from public.test_attempt_history h join public.test_attempts a on a.id=h.test_attempt_id where a.test_id=p_test;
begin
 legacy_result:=public.delete_test_atomic(p_test,p_actor);
 legacy_graph:=pg_temp.deletion_graph();
 raise exception using errcode='ZX262';
exception when sqlstate 'ZX262' then null;end;
if pg_temp.deletion_graph() is distinct from before_graph then raise exception 'Legacy rollback changed full catalog';end if;
begin
 result:=public.test_owner_workflow_v1(p_actor,p_test,parent,'delete','{}',source,clock_timestamp()+interval '25 seconds');
 if result is distinct from jsonb_build_object('version',1,'actor_id',p_actor,'classroom_id',parent,'test_id',p_test,'operation','delete','test',source,'result',legacy_result,'test_absent',true)
 or legacy_result is distinct from jsonb_build_object('deleted',true,'responses_count',count_before)
 or exists(select 1 from public.tests where id=p_test)
 or exists(select 1 from public.test_questions where test_id=p_test)
 or exists(select 1 from public.test_attempts where test_id=p_test)
 or exists(select 1 from public.test_responses where test_id=p_test)
 or exists(select 1 from public.test_attempt_history where id=any(history_ids))
 or exists(select 1 from public.test_focus_events where test_id=p_test)
 or exists(select 1 from public.test_student_availability where test_id=p_test)
 or exists(select 1 from public.test_ai_grading_runs where test_id=p_test)
 or exists(select 1 from public.test_ai_grading_run_items where test_id=p_test)
 or exists(select 1 from public.managed_storage_json_references where test_id=p_test)
 then raise exception 'Deletion acknowledgment/cascade closure differs';end if;
 -- retained Draft is intentional polymorphic legacy094 policy, never cleanup authority.
 if (select coalesce(jsonb_agg(to_jsonb(d) order by to_jsonb(d)::text),'[]') from public.assessment_drafts d where assessment_type='test' and assessment_id=p_test)
 is distinct from (select coalesce(jsonb_agg(v order by v::text),'[]') from jsonb_array_elements(before_graph->'public.assessment_drafts') v where v->>'assessment_type'='test' and v->>'assessment_id'=p_test::text)
 then raise exception 'retained Draft changed';end if;
 if exists(select 1 from public.gradebook_score_overrides where assessment_type='test' and assessment_id=p_test and classroom_id=parent) then raise exception 'Own-Class override survived';end if;
 -- foreign-Class override remains literal legacy094 behavior.
 if (select coalesce(jsonb_agg(to_jsonb(o) order by to_jsonb(o)::text),'[]') from public.gradebook_score_overrides o where assessment_type='test' and assessment_id=p_test and classroom_id<>parent)
 is distinct from (select coalesce(jsonb_agg(v order by v::text),'[]') from jsonb_array_elements(before_graph->'public.gradebook_score_overrides') v where v->>'assessment_type'='test' and v->>'assessment_id'=p_test::text and v->>'classroom_id'<>parent::text)
 then raise exception 'foreign-Class override changed';end if;
 if p_test='a2620000-0000-4000-8000-000000005008'::uuid then
 if (select to_jsonb(o) from public.managed_storage_objects o where id='a2620000-0000-4000-8000-000000005114')
 is distinct from (select v from jsonb_array_elements(before_graph->'public.managed_storage_objects') v where v->>'id'='a2620000-0000-4000-8000-000000005114')
 then raise exception 'Shared material full row changed';end if;
 if not exists(select 1 from public.managed_storage_objects where id='a2620000-0000-4000-8000-000000005114'::uuid and status='ready')
 or not exists(select 1 from public.managed_storage_json_references where test_id='a2620000-0000-4000-8000-000000005012'::uuid and managed_object_id='a2620000-0000-4000-8000-000000005114'::uuid)
 or not exists(select 1 from public.managed_storage_objects where id='a2620000-0000-4000-8000-000000005115'::uuid and status='cleanup_pending' and cleanup_reason_code='embedded_host_deleted')
 or not exists(select 1 from public.managed_storage_objects where id='a2620000-0000-4000-8000-000000005116' and status='cleanup_pending' and cleanup_reason_code='test_snapshot_reference_removed')
 or not exists(select 1 from public.test_document_snapshot_storage_cleanup where id='a2620000-0000-4000-8000-000000005117'::uuid and status='pending')
 or exists(select 1 from public.classroom_guided_draft_provenance where id='a2620000-0000-4000-8000-000000005120'::uuid)
 then raise exception 'shared material/queued cleanup/provenance differs';end if;end if;
 if exists(select 1 from public.managed_storage_objects where id in('a2620000-0000-4000-8000-000000005115'::uuid,'a2620000-0000-4000-8000-000000005116'::uuid) and (updated_at<started or updated_at>clock_timestamp() or next_attempt_at<started or next_attempt_at>clock_timestamp()) and updated_at is distinct from (select (v->>'updated_at')::timestamptz from jsonb_array_elements(before_graph->'public.managed_storage_objects') v where v->>'id'=managed_storage_objects.id::text))
 or exists(select 1 from public.test_document_snapshot_storage_cleanup o where id='a2620000-0000-4000-8000-000000005117'::uuid and updated_at is distinct from (select (v->>'updated_at')::timestamptz from jsonb_array_elements(before_graph->'public.test_document_snapshot_storage_cleanup') v where v->>'id'=o.id::text) and (updated_at<started or updated_at>clock_timestamp() or next_attempt_at<started or next_attempt_at>clock_timestamp()))
 then raise exception 'Material lifecycle timestamp invalid';end if;
 actual_graph:=pg_temp.deletion_graph();
 if pg_temp.deletion_comparable(actual_graph) is distinct from pg_temp.deletion_comparable(legacy_graph) then raise exception 'Legacy/contextual exact whole-catalog parity differs';end if;
 raise exception using errcode='ZX262';
exception when sqlstate 'ZX262' then null;end;
if pg_temp.deletion_graph() is distinct from before_graph then raise exception 'Contextual rollback changed full catalog';end if;
end;$g$;
